export const unitoolsRecipes: readonly LibraryRecipeData[] = [
  {"id":"unitools-apfelstrudel","name":"Яблочный штрудель","description":"Яблоки с корицей и изюмом в тесте, растянутом до прозрачности. Тесто тянут руками, а не раскатывают.","searchNames":["Apfelstrudel"],"category":"Десерты","tags":["Австрийская кухня"],"ingredients":[["fdc-168896",250.0,"Мука высокобелковая"],["builtin-110",125.0,"Тёплая вода","125 мл"],["fdc-172336",42.0,"Растительное масло","3 ст. л."],["fdc-168203",1000.0,"Кислые яблоки","1 кг"],["fdc-169655",100.0,"Сахар"],["fdc-171320",5.2,"Корица","2 ч. л."],["fdc-168165",80.0,"Изюм"],["fdc-174928",80.0,"Панировочные сухари"],["fdc-173430",120.0,"Сливочное масло"],["fdc-167746",58.0,"Лимон","1 шт."]],"servings":8,"prep":60,"cook":45,"difficulty":"Сложный","steps":["Замесите тесто из муки, тёплой воды, масла и щепотки соли и вымешивайте десять минут — оно должно стать гладким и очень эластичным. Смажьте маслом, накройте и оставьте на час.","Обжарьте сухари в половине масла до золотистого цвета. Яблоки смешайте с сахаром, корицей, изюмом, соком и цедрой лимона.","Расстелите на столе полотенце, присыпьте мукой и растяните тесто тыльной стороной ладоней от центра к краям, пока оно не станет прозрачным. Толстые края обрежьте.","Смажьте тесто растопленным маслом, посыпьте сухарями треть поверхности и выложите на них яблоки, отступив от краёв.","Заверните рулетом, поднимая полотенце, — руками тесто порвётся. Подверните края, переложите швом вниз и смажьте маслом.","Выпекайте при 190 °C сорок минут, смазывая маслом дважды за это время. Подавайте тёплым с сахарной пудрой."],"source":"UniTools — theunitools.com · CC BY-SA 4.0 · адаптация MassTracker","cuisine":"Австрийская кухня"},
  {"id":"unitools-trdelnik","name":"Трдельник","description":"Дрожжевая полоска теста, намотанная на валик, запечённая и обвалянная в сахаре с орехами.","searchNames":["Trdelník"],"category":"Десерты","tags":["Чешская кухня"],"ingredients":[["fdc-168936",500.0,"Мука"],["fdc-172217",226.8920923293665,"Тёплое молоко","220 мл"],["fdc-175043",7.0,"Сухие дрожжи"],["fdc-169655",60.0,"Сахар в тесто"],["fdc-173430",80.0,"Сливочное масло"],["fdc-171287",100.0,"Яйца","2 шт."],["fdc-169655",150.0,"Сахар для обваливания"],["fdc-170187",100.0,"Грецкие орехи"],["fdc-171320",5.2,"Корица","2 ч. л."],["fdc-173468",6.0,"Соль","1 ч. л."]],"servings":6,"prep":90,"cook":20,"difficulty":"Средний","steps":["Распустите дрожжи с ложкой сахара в тёплом молоке, дайте вспениться десять минут.","Замесите тесто из муки, опары, яиц, сахара и соли, вымешивайте десять минут, затем вмешивайте мягкое масло по кусочку. Дайте подойти час.","Раскатайте тесто и нарежьте полосками шириной два сантиметра. Смажьте валики маслом и обваляйте в сахаре.","Намотайте полоску на валик внахлёст на треть ширины, слегка натягивая. Прокатайте по столу, чтобы слои сцепились.","Смажьте маслом, обваляйте в смеси сахара с орехами и корицей и запекайте при 190 °C восемнадцать минут, поворачивая каждые пять.","Дайте остыть три минуты и снимите с валика, провернув. Горячий трдельник рвётся, полностью остывший прилипает."],"source":"UniTools — theunitools.com · CC BY-SA 4.0 · адаптация MassTracker","cuisine":"Чешская кухня"},
  {"id":"unitools-tabbouleh","name":"Табуле","description":"Салат из петрушки с небольшим количеством булгура, а не наоборот. Зелени здесь в десять раз больше крупы.","searchNames":["Tabbouleh"],"category":"Салаты","tags":["Ливанская кухня"],"ingredients":[["fdc-170416",200.0,"Петрушка"],["fdc-173475",30.0,"Мята"],["fdc-170688",40.0,"Мелкий булгур"],["fdc-170457",492.0,"Помидоры","4 шт."],["fdc-170005",60.0,"Зелёный лук","4 шт."],["fdc-167747",96.0,"Сок лимона","2 шт."],["fdc-171413",54.778716776985654,"Оливковое масло","60 мл"],["fdc-171315",0.95,"Душистый перец молотый","0,5 ч. л."]],"servings":4,"prep":25,"cook":0,"difficulty":"Простой","steps":["Промойте булгур и залейте соком одного лимона. Оставьте набухать пятнадцать минут.","Вымойте петрушку заранее и обсушите досуха — лучше час на полотенце. Оборвите толстые стебли и рубите ножом мелко, но без фанатизма.","Нарежьте помидоры мелким кубиком и посолите отдельно — они пустят сок, который пойдёт в булгур.","Смешайте всё вместе с соком второго лимона, маслом и душистым перцем. Дайте постоять десять минут перед подачей."],"source":"UniTools — theunitools.com · CC BY-SA 4.0 · адаптация MassTracker","cuisine":"Ливанская кухня","seasoningNote":"По вкусу, вне расчёта КБЖУ: Соль."},
  {"id":"unitools-croissant","name":"Круассан","description":"Слоёное дрожжевое тесто с двадцатью семью слоями масла. Всё решает температура: тесто и масло должны быть одинаково холодными.","searchNames":["Croissant"],"category":"Выпечка","tags":["Французская кухня"],"ingredients":[["fdc-168896",500.0,"Мука высокобелковая"],["fdc-172217",288.77175387373916,"Холодное молоко","280 мл"],["fdc-175042",15.0,"Свежие дрожжи"],["fdc-169655",55.0,"Сахар"],["fdc-173468",11.0,"Соль"],["fdc-173430",40.0,"Масло в тесто"],["fdc-173430",280.0,"Масло для слоения"],["fdc-171287",50.0,"Яйцо для смазки","1 шт."]],"servings":8,"prep":180,"cook":20,"difficulty":"Сложный","steps":["Замесите тесто из муки, холодного молока, дрожжей, сахара, соли и мягкого масла пять минут. Не перемешивайте дольше: сильная клейковина помешает раскатке.","Расплющите тесто в прямоугольник, заверните и уберите в холодильник минимум на четыре часа, лучше на ночь.","Отбейте холодное масло скалкой в квадрат толщиной в сантиметр и держите в холоде. Оно должно гнуться, но не ломаться и не таять.","Раскатайте тесто вдвое больше масляного квадрата, положите масло по центру и заверните края конвертом, защипнув швы.","Раскатайте в длинный прямоугольник и сложите втрое. Уберите в холод на сорок минут. Повторите ещё два раза — всего три сложения.","Раскатайте пласт толщиной четыре миллиметра, нарежьте треугольниками с основанием десять сантиметров и сверните от основания к вершине, слегка натягивая.","Расстаивайте два часа при 25 °C — не теплее, иначе масло вытечет. Смажьте яйцом и выпекайте при 200 °C восемнадцать минут."],"source":"UniTools — theunitools.com · CC BY-SA 4.0 · адаптация MassTracker","cuisine":"Французская кухня"},
  {"id":"unitools-baklava","name":"Пахлава","description":"Сорок слоёв юфки с фисташками, залитые сиропом. Горячая пахлава заливается холодным сиропом, и только так.","searchNames":["Baklava"],"category":"Десерты","tags":["Турецкая кухня"],"ingredients":[["fdc-172791",500.0,"Тесто юфка или фило"],["fdc-170184",400.0,"Фисташки"],["fdc-171314",300.0,"Топлёное масло"],["fdc-169655",500.0,"Сахар"],["builtin-110",400.0,"Вода","400 мл"],["fdc-167747",15.25,"Лимонный сок","1 ст. л."]],"servings":12,"prep":60,"cook":60,"difficulty":"Сложный","steps":["Сварите сироп: сахар с водой довести до кипения, варить пятнадцать минут, добавить лимонный сок и полностью остудить.","Растопите масло и дайте отстояться — используйте только прозрачный верхний слой, осадок вылейте.","Уложите в смазанную форму двадцать листов, смазывая каждый маслом. Посыпьте фисташками ровным слоем.","Накройте ещё двадцатью листами, так же смазывая каждый. Верхний слой смажьте особенно щедро.","Разрежьте острым ножом на ромбы до самого дна формы.","Выпекайте при 170 °C час до глубокого золотого цвета. Достаньте и сразу залейте холодным сиропом по надрезам.","Оставьте на шесть часов, лучше на ночь. Резать и подавать раньше бессмысленно: сироп не дошёл до нижних слоёв."],"source":"UniTools — theunitools.com · CC BY-SA 4.0 · адаптация MassTracker","cuisine":"Турецкая кухня"},
  {"id":"unitools-karjalanpiirakka","name":"Карельские пирожки","description":"Ржаная корзиночка с рисовой кашей, смазанная маслом после выпечки и поданная с яичным маслом.","searchNames":["Karelian pies"],"category":"Выпечка","tags":["Финская кухня"],"ingredients":[["fdc-168886",250.0,"Ржаная мука"],["builtin-110",150.0,"Вода","150 мл"],["fdc-168881",150.0,"Круглый рис"],["fdc-172217",721.929384684348,"Молоко","700 мл"],["fdc-173430",100.0,"Сливочное масло"],["fdc-171287",150.0,"Яйца","3 шт."]],"servings":8,"prep":60,"cook":25,"difficulty":"Сложный","steps":["Сварите рис в молоке на слабом огне сорок минут до состояния жидковатой каши. Посолите и остудите.","Замесите тесто из ржаной муки, воды и соли, вымешивайте пять минут. Оно будет плотным и не липким.","Разделите на шестнадцать шариков и раскатайте каждый в овал толщиной в полмиллиметра. Подпыляйте ржаной мукой, а не пшеничной.","Выложите ложку каши по центру, оставив свободными края, и защипните края гофрировкой, оставив начинку открытой.","Выпекайте при 250 °C пятнадцать минут — коротко и очень горячо, иначе тонкое тесто высохнет.","Растопите половину масла с равным количеством горячей воды и окуните горячие пирожки. Накройте полотенцем на десять минут.","Разомните варёные яйца с оставшимся мягким маслом и солью — это мунавой, яичное масло. Подавайте им пирожки."],"source":"UniTools — theunitools.com · CC BY-SA 4.0 · адаптация MassTracker","cuisine":"Финская кухня","seasoningNote":"По вкусу, вне расчёта КБЖУ: Соль."},
  {"id":"unitools-soda-bread","name":"Содовый хлеб","description":"Хлеб на соде и пахте без дрожжей и без расстойки. От замеса до духовки — три минуты.","searchNames":["Soda bread"],"category":"Выпечка","tags":["Ирландская кухня"],"ingredients":[["fdc-168936",350.0,"Мука"],["fdc-168893",150.0,"Цельнозерновая мука"],["fdc-172225",414.2217780975767,"Пахта","400 мл"],["fdc-175040",4.6,"Сода","1 ч. л."],["fdc-173468",6.0,"Соль","1 ч. л."],["fdc-173904",10.227272727272727,"Овсяные хлопья","2 ст. л."]],"servings":8,"prep":10,"cook":45,"difficulty":"Простой","steps":["Разогрейте духовку до 220 °C заранее. Хлеб должен отправиться в неё сразу после замеса, ждать он не может.","Смешайте обе муки, соду и соль в миске и хорошо перемешайте, чтобы сода разошлась равномерно.","Влейте пахту и перемешайте ножом или рукой ровно до соединения. Тесто будет липким и неровным — так и надо.","Выложите на присыпанный мукой противень, придайте форму круглой буханки и прорежьте глубокий крест почти до дна.","Посыпьте овсяными хлопьями и выпекайте пятнадцать минут при 220 °C, затем тридцать при 190 °C.","Готовый хлеб звучит глухо, если постучать по дну. Остудите на решётке минимум час: горячий содовый хлеб не режется."],"source":"UniTools — theunitools.com · CC BY-SA 4.0 · адаптация MassTracker","cuisine":"Ирландская кухня"},
  {"id":"unitools-zagorski-strukli","name":"Загорски штрукли","description":"Тонкое тесто с творожной начинкой, отваренное и запечённое под сливками.","searchNames":["Zagorje štrukli"],"category":"Основные блюда","tags":["Хорватская кухня"],"ingredients":[["fdc-168936",300.0,"Мука"],["builtin-110",150.0,"Тёплая вода","150 мл"],["fdc-172336",28.0,"Растительное масло","2 ст. л."],["fdc-171287",50.0,"Яйцо","1 шт."],["fdc-172181",600.0,"Сухой творог"],["fdc-171287",100.0,"Яйца в начинку","2 шт."],["fdc-171257",200.0,"Сметана"],["fdc-170859",251.91446912873033,"Сливки","250 мл"],["fdc-173430",60.0,"Сливочное масло"]],"servings":6,"prep":60,"cook":45,"difficulty":"Сложный","steps":["Замесите тесто из муки, тёплой воды, масла, яйца и соли и вымешивайте десять минут до эластичности. Смажьте маслом и оставьте на полчаса.","Разомните творог вилкой с яйцами, сметаной и солью. Начинка должна быть плотной, а не текучей.","Растяните тесто на полотенце руками до прозрачности, смажьте растопленным маслом и разложите начинку по трети поверхности.","Сверните рулетом, поднимая полотенце, и нарежьте на куски по восемь сантиметров, прижимая края ребром ладони, чтобы они запечатались.","Отварите в подсоленной воде пять минут после всплытия и выньте шумовкой.","Уложите в форму, залейте сливками, полейте растопленным маслом и запекайте при 200 °C двадцать пять минут до румяной корочки."],"source":"UniTools — theunitools.com · CC BY-SA 4.0 · адаптация MassTracker","cuisine":"Хорватская кухня","seasoningNote":"По вкусу, вне расчёта КБЖУ: Соль."},
  {"id":"unitools-saltibarsciai","name":"Шалтибарщяй","description":"Холодный свекольный суп на кефире, ярко-розовый, с огурцом, укропом и варёной картошкой отдельно.","searchNames":["Šaltibarščiai"],"category":"Супы","tags":["Литовская кухня"],"ingredients":[["fdc-169145",500.0,"Свёкла"],["fdc-170904",1027.1009395684812,"Кефир","1 л"],["fdc-168409",602.0,"Огурцы","2 шт."],["fdc-171287",200.0,"Яйца","4 шт."],["fdc-172233",40.0,"Укроп"],["fdc-170005",40.0,"Зелёный лук"],["fdc-170026",800.0,"Картофель"],["fdc-171257",145.82297290169794,"Сметана","150 мл"]],"servings":4,"prep":20,"cook":40,"difficulty":"Простой","steps":["Отварите свёклу до мягкости, остудите полностью и натрите на крупной тёрке.","Нарежьте огурцы соломкой, порубите укроп и зелёный лук.","Смешайте свёклу, огурцы и зелень со сметаной и посолите — до кефира, чтобы соль разошлась.","Влейте холодный кефир и размешайте. Суп станет ровного розового цвета.","Уберите в холодильник на час. Тёплый шалтибарщяй не имеет смысла.","Отварите картофель и подайте горячим на отдельной тарелке. В суп положите половинки яиц."],"source":"UniTools — theunitools.com · CC BY-SA 4.0 · адаптация MassTracker","cuisine":"Литовская кухня","seasoningNote":"По вкусу, вне расчёта КБЖУ: Соль."},
  {"id":"unitools-draniki","name":"Драники","description":"Картофельные оладьи из тёртого сырого картофеля, жаренные до хрустящей корки, со сметаной.","searchNames":["Draniki"],"category":"Основные блюда","tags":["Белорусская кухня"],"ingredients":[["fdc-170026",1000.0,"Картофель","1 кг"],["fdc-170000",110.0,"Лук","1 шт."],["fdc-172336",92.14321186252216,"Растительное масло","100 мл"],["fdc-171257",194.43063053559723,"Сметана","200 мл"],["fdc-172233",20.0,"Укроп"]],"servings":4,"prep":20,"cook":25,"difficulty":"Простой","steps":["Натрите картофель и лук на мелкой тёрке в одну миску.","Дайте массе постоять три минуты и слейте отстоявшуюся сверху воду, не трогая осадок.","Посолите и поперчите. Ничего больше не добавляйте.","Разогрейте масло на среднем огне и выкладывайте массу столовой ложкой, приплющивая до толщины в полсантиметра.","Жарьте по три-четыре минуты с каждой стороны до тёмно-золотой хрустящей корки.","Выложите на бумагу и подавайте немедленно со сметаной и укропом."],"source":"UniTools — theunitools.com · CC BY-SA 4.0 · адаптация MassTracker","cuisine":"Белорусская кухня","seasoningNote":"По вкусу, вне расчёта КБЖУ: Соль и перец."},
  {"id":"unitools-chakalaka","name":"Чакалака","description":"Острая овощная закуска из моркови, перца и фасоли с карри. К брааю, к пап или сама по себе.","searchNames":["Chakalaka"],"category":"Гарниры","tags":["Южноафриканская кухня"],"ingredients":[["fdc-170393",244.0,"Морковь","4 шт."],["fdc-170108",357.0,"Перец сладкий","3 шт."],["fdc-170000",220.0,"Лук","2 шт."],["fdc-175182",400.0,"Фасоль в томате"],["fdc-170457",400.0,"Помидоры"],["fdc-170924",6.3,"Карри молотое","1 ст. л."],["fdc-171329",2.3,"Паприка","1 ч. л."],["fdc-170106",90.0,"Перец чили","2 шт."],["fdc-169230",12.0,"Чеснок","4 зубч."],["fdc-169231",20.0,"Имбирь"],["fdc-172336",46.07160593126108,"Растительное масло","50 мл"]],"servings":6,"prep":20,"cook":20,"difficulty":"Простой","steps":["Натрите морковь на крупной тёрке, перец и лук нарежьте тонкой соломкой.","Обжарьте лук с чесноком, имбирём и чили в масле до мягкости, пять минут.","Добавьте карри и паприку и прогрейте минуту — специи должны раскрыться в масле.","Всыпьте перец и морковь и жарьте пять минут на сильном огне, помешивая.","Влейте помидоры, посолите и тушите семь минут, пока соус не загустеет.","Вмешайте фасоль, прогрейте три минуты и снимите с огня. Овощи должны остаться упругими."],"source":"UniTools — theunitools.com · CC BY-SA 4.0 · адаптация MassTracker","cuisine":"Южноафриканская кухня","seasoningNote":"По вкусу, вне расчёта КБЖУ: Соль и перец."},
  {"id":"unitools-burek-bosanski","name":"Боснийский бурек","description":"Спираль из тончайшего вытянутого теста с мясной начинкой. В Боснии буреком называют только мясной.","searchNames":["Bosnian burek"],"category":"Основные блюда","tags":["Боснийская кухня"],"ingredients":[["fdc-168936",500.0,"Мука"],["builtin-110",280.0,"Вода тёплая","280 мл"],["fdc-171796",600.0,"Говяжий фарш"],["fdc-170000",220.0,"Лук","2 шт."],["fdc-172336",138.21481779378325,"Растительное масло","150 мл"],["fdc-172237",5.0,"Уксус","1 ч. л."],["fdc-171284",414.2217780975767,"Йогурт","400 мл"]],"servings":6,"prep":75,"cook":45,"difficulty":"Сложный","steps":["Замесите тесто из муки, тёплой воды, ложки масла, уксуса и соли и вымешивайте пятнадцать минут до эластичности.","Разделите на четыре шара, смажьте маслом, накройте и оставьте на сорок минут.","Смешайте сырой фарш с луком, солью, перцем и двумя ложками воды — вода нужна, чтобы начинка не пересохла.","Растяните шар руками на застеленном скатертью столе до прозрачного листа, начиная от центра и двигаясь к краям.","Сбрызните лист маслом, выложите начинку полосой вдоль края и сверните в длинный тонкий рулет.","Уложите рулеты спиралью в круглую форму от центра, смажьте маслом и пеките при 200 °C сорок минут.","Сбрызните горячий бурек водой и накройте полотенцем на пять минут — корка станет мягче. Подавайте с йогуртом."],"source":"UniTools — theunitools.com · CC BY-SA 4.0 · адаптация MassTracker","cuisine":"Боснийская кухня","seasoningNote":"По вкусу, вне расчёта КБЖУ: Соль и перец."},
  {"id":"unitools-byrek-me-spinaq","name":"Бюрек со шпинатом","description":"Пирог из тонкого теста со шпинатом и брынзой, слоями, залитыми маслом.","searchNames":["Byrek me spinaq"],"category":"Основные блюда","tags":["Албанская кухня"],"ingredients":[["fdc-172791",500.0,"Тесто фило"],["fdc-168462",1000.0,"Шпинат","1 кг"],["fdc-173420",400.0,"Брынза"],["fdc-170005",90.0,"Зелёный лук","6 шт."],["fdc-171413",164.33615033095697,"Оливковое масло","180 мл"],["fdc-172233",30.0,"Укроп"]],"servings":8,"prep":35,"cook":45,"difficulty":"Простой","steps":["Ошпарьте шпинат кипятком, откиньте и отожмите руками досуха.","Нарежьте шпинат, смешайте с раскрошенной брынзой, зелёным луком, укропом и перцем. Соль добавляйте осторожно — брынза солёная.","Смажьте форму маслом и уложите три листа фило, промазывая каждый.","Распределите треть начинки, накройте двумя листами с маслом и повторите ещё дважды.","Закройте тремя листами сверху, подверните края внутрь и щедро смажьте маслом.","Нарежьте квадратами до низа острым ножом — резать после выпечки не получится.","Пеките при 190 °C сорок пять минут до тёмно-золотой хрустящей корки."],"source":"UniTools — theunitools.com · CC BY-SA 4.0 · адаптация MassTracker","cuisine":"Албанская кухня","seasoningNote":"По вкусу, вне расчёта КБЖУ: Соль и перец."},
  {"id":"unitools-flia","name":"Флия","description":"Слоёный пирог из жидкого теста, наливаемого по одному слою под раскалённой крышкой саче.","searchNames":["Flia"],"category":"Основные блюда","tags":["Косовская кухня"],"ingredients":[["fdc-168936",600.0,"Мука"],["builtin-110",900.0,"Вода","900 мл"],["fdc-171257",388.86126107119446,"Сметана","400 мл"],["fdc-173430",150.0,"Сливочное масло"],["fdc-171284",310.66633357318256,"Йогурт","300 мл"],["fdc-169640",100.0,"Мёд"],["fdc-173468",12.0,"Соль","2 ч. л."]],"servings":8,"prep":30,"cook":90,"difficulty":"Сложный","steps":["Взбейте муку с водой и солью в жидкое тесто без комков — гуще блинного, но текучее.","Разведите сметану холодной водой до консистенции жидких сливок и посолите.","Смажьте круглую форму маслом и налейте тесто полосами от центра к краям, как спицы колеса.","Поставьте под верхний гриль на четыре минуты, пока слой не схватится и не пойдёт пятнами.","Сбрызните разведённой сметаной и налейте следующий слой в промежутки между предыдущими полосами.","Повторяйте, чередуя направление полос, пока тесто не кончится — обычно двадцать-двадцать пять слоёв.","Полейте растопленным маслом, дайте постоять десять минут и подавайте с йогуртом или мёдом."],"source":"UniTools — theunitools.com · CC BY-SA 4.0 · адаптация MassTracker","cuisine":"Косовская кухня"},
  {"id":"unitools-rolex-uganda","name":"Ролекс","description":"Омлет с овощами, завёрнутый в лепёшку чапати. Уличная еда Кампалы, названная от «rolled eggs».","searchNames":["Rolex"],"category":"Завтраки","tags":["Угандийская кухня"],"ingredients":[["fdc-168936",400.0,"Мука"],["builtin-110",240.0,"Вода тёплая","240 мл"],["fdc-171287",400.0,"Яйца","8 шт."],["fdc-169975",200.0,"Капуста"],["fdc-170457",369.0,"Помидоры","3 шт."],["fdc-170000",220.0,"Лук","2 шт."],["fdc-170393",61.0,"Морковь","1 шт."],["fdc-170106",45.0,"Перец чили","1 шт."],["fdc-172336",110.5718542350266,"Растительное масло","120 мл"]],"servings":4,"prep":35,"cook":30,"difficulty":"Простой","steps":["Замесите мягкое тесто из муки, тёплой воды, ложки масла и соли и оставьте на двадцать минут.","Раскатайте шар тонко, смажьте маслом, сверните жгутом, закрутите улиткой и раскатайте снова.","Жарьте чапати на среднем огне по полторы минуты с каждой стороны и держите под полотенцем.","Нашинкуйте капусту, морковь, лук, помидоры и чили как можно тоньше.","Взбейте яйца с овощами, солью и перцем — овощи должны быть внутри омлета, а не сверху.","Вылейте порцию яиц на сковороду, дайте схватиться и положите сверху чапати, прижав лопаткой.","Переверните вместе, снимите на доску омлетом вверх и сверните плотным рулетом."],"source":"UniTools — theunitools.com · CC BY-SA 4.0 · адаптация MassTracker","cuisine":"Угандийская кухня","seasoningNote":"По вкусу, вне расчёта КБЖУ: Соль и перец."},
  {"id":"unitools-muriwo-unedovi","name":"Зелень в арахисовом соусе","description":"Листовая капуста, тушённая в арахисовой пасте с помидором. Гарнир к садзе в каждом доме.","searchNames":["Muriwo unedovi"],"category":"Гарниры","tags":["Зимбабвийская кухня"],"ingredients":[["fdc-170406",700.0,"Листовая капуста"],["fdc-172459",150.0,"Арахисовая паста"],["fdc-170000",110.0,"Лук","1 шт."],["fdc-170457",369.0,"Помидоры","3 шт."],["fdc-169230",9.0,"Чеснок","3 зубч."],["fdc-172336",36.85728474500887,"Растительное масло","40 мл"]],"servings":4,"prep":15,"cook":25,"difficulty":"Простой","steps":["Снимите с листьев жёсткие черешки, сверните листья рулоном и нарежьте тонкой соломкой.","Обжарьте лук и чеснок в масле до мягкости, пять минут.","Добавьте нарезанные помидоры и тушите семь минут, пока они не разойдутся в пасту.","Разведите арахисовую пасту стаканом горячей воды до однородности без комков.","Вмешайте зелень и разведённую пасту, посолите и тушите под крышкой двенадцать минут.","Снимите крышку и выпарите лишнюю жидкость — соус должен держаться на листьях."],"source":"UniTools — theunitools.com · CC BY-SA 4.0 · адаптация MassTracker","cuisine":"Зимбабвийская кухня","seasoningNote":"По вкусу, вне расчёта КБЖУ: Соль и перец."},
  {"id":"unitools-melanzane-alla-parmigiana","name":"Пармиджана из баклажанов","description":"Слои жареных баклажанов с томатным соусом, моцареллой и пармезаном, запечённые до корки.","searchNames":["Melanzane alla parmigiana"],"category":"Основные блюда","tags":["Итальянская кухня"],"ingredients":[["fdc-169228",1500.0,"Баклажаны","1,5 кг"],["fdc-170051",800.0,"Томаты в собственном соку"],["fdc-170845",400.0,"Моцарелла"],["fdc-170848",150.0,"Пармезан"],["fdc-172232",30.0,"Базилик"],["fdc-169230",9.0,"Чеснок","3 зубч."],["fdc-171413",182.59572258995217,"Оливковое масло","200 мл"]],"servings":6,"prep":50,"cook":60,"difficulty":"Средний","steps":["Нарежьте баклажаны вдоль ломтями в полсантиметра, посолите и оставьте под грузом на полчаса.","Обсушите ломти насухо бумагой — на мокрых масло будет брызгать, а корка не образуется.","Обжарьте баклажаны партиями в оливковом масле по две минуты с каждой стороны и выложите на решётку.","Обжарьте чеснок, добавьте томаты и варите соус двадцать минут до густоты, посолив в конце.","Нарежьте моцареллу и оставьте на бумаге стекать десять минут.","Собирайте слоями: соус, баклажаны, моцарелла, пармезан, базилик — и так четыре раза.","Запекайте при 190 °C сорок минут и дайте постоять двадцать перед нарезкой."],"source":"UniTools — theunitools.com · CC BY-SA 4.0 · адаптация MassTracker","cuisine":"Итальянская кухня","seasoningNote":"По вкусу, вне расчёта КБЖУ: Соль и перец."},
  {"id":"unitools-gemista","name":"Гемиста","description":"Помидоры и перцы, фаршированные рисом с зеленью и запечённые с картофелем в оливковом масле.","searchNames":["Gemista"],"category":"Основные блюда","tags":["Греческая кухня"],"ingredients":[["fdc-170457",1456.0,"Помидоры крупные","8 шт."],["fdc-170108",476.0,"Перец сладкий","4 шт."],["fdc-168881",300.0,"Рис круглозёрный"],["fdc-170000",330.0,"Лук","3 шт."],["fdc-170026",600.0,"Картофель"],["fdc-170416",50.0,"Петрушка"],["fdc-173475",20.0,"Мята"],["fdc-172233",30.0,"Укроп"],["fdc-171413",182.59572258995217,"Оливковое масло","200 мл"],["fdc-169655",4.2,"Сахар","1 ч. л."]],"servings":6,"prep":45,"cook":80,"difficulty":"Простой","steps":["Срежьте у помидоров крышечки и выберите мякоть ложкой, не повредив стенки.","Пробейте мякоть блендером и добавьте сахар — он уберёт кислоту помидоров.","Обжарьте лук в оливковом масле десять минут до мягкости и сладости.","Смешайте сырой рис с луком, зеленью, половиной томатного пюре, солью и перцем.","Наполните овощи на две трети, накройте крышечками и поставьте в форму.","Разложите между ними картофель дольками, залейте оставшимся пюре и щедро полейте маслом.","Запекайте под фольгой при 180 °C час, потом снимите фольгу и держите ещё двадцать минут."],"source":"UniTools — theunitools.com · CC BY-SA 4.0 · адаптация MassTracker","cuisine":"Греческая кухня","seasoningNote":"По вкусу, вне расчёта КБЖУ: Соль и перец."},
  {"id":"unitools-beef-stroganoff","name":"Бефстроганов","description":"Говядина, нарезанная соломкой и обжаренная на сильном огне, в сметанном соусе с луком.","searchNames":["Beef Stroganoff"],"category":"Основные блюда","tags":["Русская кухня"],"ingredients":[["fdc-169542",700.0,"Говяжья вырезка"],["fdc-170000",220.0,"Лук","2 шт."],["fdc-169251",300.0,"Шампиньоны"],["fdc-171257",291.6459458033959,"Сметана","300 мл"],["fdc-172234",15.5625,"Горчица","1 ст. л."],["fdc-168936",15.625,"Мука","2 ст. л."],["fdc-172883",202.884136211058,"Говяжий бульон","200 мл"],["fdc-173430",60.0,"Сливочное масло"],["fdc-172336",27.64296355875665,"Растительное масло","30 мл"],["fdc-170416",20.0,"Петрушка"]],"servings":4,"prep":20,"cook":25,"difficulty":"Простой","steps":["Нарежьте мясо поперёк волокон соломкой толщиной в сантиметр, обсушите бумагой и поперчите.","Раскалите сковороду и обжарьте мясо порциями по полторы минуты, не переворачивая часто.","Выньте мясо, обжарьте грибы на сильном огне до испарения их воды.","Добавьте масло и лук и жарьте до мягкости и золотистого цвета.","Всыпьте муку, прогрейте минуту и влейте бульон, размешивая до гладкости.","Снимите с огня, вмешайте сметану и горчицу и посолите.","Верните мясо с выделившимся соком, прогрейте минуту не кипятя и посыпьте петрушкой."],"source":"UniTools — theunitools.com · CC BY-SA 4.0 · адаптация MassTracker","cuisine":"Русская кухня","seasoningNote":"По вкусу, вне расчёта КБЖУ: Соль и перец."},
  {"id":"unitools-chapati-kenyan","name":"Кенийская чапати","description":"Слоёная мягкая лепёшка из пшеничного теста, свёрнутого спиралью перед раскаткой.","searchNames":["Kenyan chapati"],"category":"Выпечка","tags":["Кенийская кухня"],"ingredients":[["fdc-168936",600.0,"Мука"],["builtin-110",350.0,"Вода тёплая","350 мл"],["fdc-172336",138.21481779378325,"Растительное масло","150 мл"],["fdc-169655",12.5,"Сахар","1 ст. л."],["fdc-173468",9.0,"Соль","1,5 ч. л."]],"servings":8,"prep":75,"cook":30,"difficulty":"Средний","steps":["Смешайте муку с солью и сахаром, влейте тёплую воду и две ложки масла.","Вымешивайте тесто пятнадцать минут, пока оно не станет гладким и эластичным.","Накройте влажным полотенцем и дайте отдохнуть час при комнатной температуре.","Разделите на восемь шаров, раскатайте каждый в тонкий круг и щедро смажьте маслом.","Сверните круг в жгут, закрутите улиткой и придавите ладонью.","Дайте улиткам постоять пятнадцать минут и раскатайте каждую в круг заново.","Жарьте на сухой сковороде по полторы минуты с каждой стороны, смазывая маслом, до румяных пятен."],"source":"UniTools — theunitools.com · CC BY-SA 4.0 · адаптация MassTracker","cuisine":"Кенийская кухня"},
  {"id":"unitools-montreal-bagels","name":"Монреальские бейглы","description":"Бейглы, отваренные в медовой воде и запечённые в дровяной печи, слаще и тоньше нью-йоркских.","searchNames":["Montreal bagels"],"category":"Выпечка","tags":["Канадская кухня"],"ingredients":[["fdc-168896",700.0,"Мука сильная"],["builtin-110",300.0,"Вода тёплая","300 мл"],["fdc-175043",10.0,"Сухие дрожжи"],["fdc-171287",100.0,"Яйца","2 шт."],["fdc-172336",55.2859271175133,"Растительное масло","60 мл"],["fdc-169655",60.0,"Сахар"],["fdc-169640",150.0,"Мёд"],["fdc-170150",150.0,"Кунжут"],["fdc-171330",100.0,"Мак"],["fdc-173468",6.0,"Соль","1 ч. л."]],"servings":12,"prep":120,"cook":25,"difficulty":"Сложный","steps":["Растворите дрожжи с сахаром в тёплой воде и оставьте на десять минут до пены.","Замесите тесто из муки, опары, яиц, масла и соли и вымешивайте пятнадцать минут до эластичности.","Дайте подойти в тепле час двадцать, пока тесто не удвоится.","Разделите на двенадцать частей, раскатайте жгутами и соедините концы кольцом с крупным отверстием.","Вскипятите большую кастрюлю воды с мёдом и опускайте кольца по три-четыре штуки.","Варите по минуте с каждой стороны и сразу обваливайте в кунжуте или маке.","Пеките при 230 °C двадцать минут до тёмно-золотой корки, перевернув один раз на середине."],"source":"UniTools — theunitools.com · CC BY-SA 4.0 · адаптация MassTracker","cuisine":"Канадская кухня"},
  {"id":"unitools-arroz-con-coco","name":"Рис с кокосом","description":"Рис на кокосовом молоке с карамелизованными шкварками кокоса, тёмный и слегка сладкий.","searchNames":["Coconut rice"],"category":"Гарниры","tags":["Панамская кухня"],"ingredients":[["fdc-168877",500.0,"Рис длиннозёрный"],["fdc-170173",764.1969130616517,"Кокосовое молоко","800 мл"],["builtin-110",400.0,"Вода","400 мл"],["fdc-169655",25.0,"Сахар","2 ст. л."],["fdc-168165",80.0,"Изюм"],["fdc-173468",9.0,"Соль","1,5 ч. л."]],"servings":6,"prep":15,"cook":45,"difficulty":"Средний","steps":["Влейте кокосовое молоко в казан и варите на среднем огне, помешивая.","Продолжайте варить, пока молоко не разделится на масло и коричневые шкварки.","Как только шкварки станут тёмно-коричневыми, сразу влейте воду, чтобы остановить карамелизацию.","Добавьте сахар, соль и изюм и доведите до кипения.","Промойте рис до прозрачной воды и всыпьте в кастрюлю ровным слоем.","Варите на среднем огне без крышки, пока жидкость не сравняется с уровнем риса.","Накройте, убавьте огонь до минимума и держите двадцать минут, ни разу не открывая."],"source":"UniTools — theunitools.com · CC BY-SA 4.0 · адаптация MassTracker","cuisine":"Панамская кухня"},
  {"id":"unitools-kugelis","name":"Кугелис","description":"Картофельная запеканка из тёртого сырого картофеля с беконом и луком, со сметаной.","searchNames":["Kugelis"],"category":"Основные блюда","tags":["Литовская кухня"],"ingredients":[["fdc-170026",2000.0,"Картофель","2 кг"],["fdc-168277",300.0,"Копчёная грудинка"],["fdc-170000",330.0,"Лук","3 шт."],["fdc-171287",150.0,"Яйца","3 шт."],["fdc-172217",206.26553848124226,"Молоко","200 мл"],["fdc-171257",291.6459458033959,"Сметана","300 мл"],["fdc-170928",0.6,"Майоран","1 ч. л."]],"servings":8,"prep":35,"cook":95,"difficulty":"Средний","steps":["Вытопите грудинку до шкварок, добавьте нарезанный лук и жарьте до золотистого цвета.","Натрите картофель на мелкой тёрке и слегка отожмите, собрав жидкость в миску.","Дайте жидкости отстояться десять минут, слейте воду и вмешайте осевший крахмал обратно.","Влейте горячее молоко и горячий жир с луком и шкварками, размешивая быстро.","Вмешайте яйца, соль, перец и майоран до однородной густой массы.","Вылейте в смазанную форму слоем в четыре сантиметра и разровняйте.","Запекайте при 180 °C полтора часа до тёмно-золотой корки и дайте постоять двадцать минут."],"source":"UniTools — theunitools.com · CC BY-SA 4.0 · адаптация MassTracker","cuisine":"Литовская кухня","seasoningNote":"По вкусу, вне расчёта КБЖУ: Соль и перец."},
  {"id":"unitools-sklandrausis","name":"Складраусис","description":"Ржаная корзиночка с двумя слоями пюре — картофельным и морковным, с корицей.","searchNames":["Sklandrausis"],"category":"Десерты","tags":["Латвийская кухня"],"ingredients":[["fdc-168886",400.0,"Ржаная мука"],["builtin-110",180.0,"Вода тёплая","180 мл"],["fdc-173430",80.0,"Сливочное масло"],["fdc-170026",500.0,"Картофель"],["fdc-170393",600.0,"Морковь"],["fdc-171257",194.43063053559723,"Сметана","200 мл"],["fdc-171287",100.0,"Яйца","2 шт."],["fdc-169655",80.0,"Сахар"],["fdc-170918",2.1,"Тмин","1 ч. л."],["fdc-171320",2.6,"Корица","1 ч. л."],["fdc-173468",6.0,"Соль","1 ч. л."]],"servings":10,"prep":60,"cook":30,"difficulty":"Средний","steps":["Замесите тесто из ржаной муки, тёплой воды, растопленного масла и соли и дайте отдохнуть полчаса.","Отварите картофель и морковь по отдельности до полной мягкости.","Разомните картофель со сметаной, яйцом, тмином и солью в гладкое пюре.","Разомните морковь со сметаной, яйцом, сахаром и корицей в отдельное пюре.","Раскатайте тесто тонко, вырежьте круги и сформуйте бортики пальцами, подворачивая края.","Выложите картофельное пюре первым слоем, сверху морковное, разровняйте ложкой.","Пеките при 200 °C двадцать пять минут и посыпьте корицей ещё горячими."],"source":"UniTools — theunitools.com · CC BY-SA 4.0 · адаптация MassTracker","cuisine":"Латвийская кухня"},
  {"id":"unitools-skabu-putra","name":"Скабу путра","description":"Холодная перловая каша на кислом молоке, латвийская еда полевого дня.","searchNames":["Skābputra"],"category":"Супы","tags":["Латвийская кухня"],"ingredients":[["fdc-170284",250.0,"Перловая крупа"],["builtin-110",1500.0,"Вода","1,5 л"],["fdc-172225",1035.5544452439417,"Простокваша или пахта","1 л"],["fdc-171257",145.82297290169794,"Сметана","150 мл"],["fdc-170005",40.0,"Зелёный лук"],["fdc-172233",30.0,"Укроп"],["fdc-170026",600.0,"Картофель"]],"servings":5,"prep":15,"cook":70,"difficulty":"Простой","steps":["Промойте перловку и замочите её в холодной воде на два часа.","Отварите крупу в полутора литрах воды час, пока она не разварится полностью.","Посолите кашу и полностью остудите её, помешивая, чтобы не образовалась плёнка.","Вмешайте простоквашу в холодную кашу постепенно, добиваясь консистенции густого супа.","Оставьте на четыре часа в холодном месте, чтобы вкус закислился и выровнялся.","Отварите картофель в мундире и подайте его горячим отдельно.","Разлейте по мискам, добавьте сметану и посыпьте зелёным луком и укропом."],"source":"UniTools — theunitools.com · CC BY-SA 4.0 · адаптация MassTracker","cuisine":"Латвийская кухня","seasoningNote":"По вкусу, вне расчёта КБЖУ: Соль."},
  {"id":"unitools-gurasa","name":"Гураса","description":"Толстая суданская лепёшка на сковороде, поданная с мясным рагу или соусом.","searchNames":["Gurasa"],"category":"Выпечка","tags":["Суданская кухня"],"ingredients":[["fdc-168936",500.0,"Мука"],["builtin-110",550.0,"Вода тёплая","550 мл"],["fdc-175043",7.0,"Сухие дрожжи"],["fdc-169655",12.5,"Сахар","1 ст. л."],["fdc-172336",36.85728474500887,"Растительное масло","40 мл"],["fdc-173468",6.0,"Соль","1 ч. л."]],"servings":6,"prep":80,"cook":30,"difficulty":"Простой","steps":["Разведите дрожжи с сахаром в тёплой воде и оставьте на десять минут до пены.","Всыпьте муку с солью и размешайте венчиком до гладкого жидкого теста без комков.","Влейте масло и вымешайте ещё минуту, пока тесто не станет глянцевым.","Накройте и оставьте в тепле на час, пока по поверхности не пойдут пузыри.","Разогрейте сухую сковороду на среднем огне и вылейте половник теста.","Накройте крышкой и жарьте пять минут, пока верх не схватится и не станет матовым.","Снимите, не переворачивая, и складывайте стопкой под полотенце."],"source":"UniTools — theunitools.com · CC BY-SA 4.0 · адаптация MassTracker","cuisine":"Суданская кухня"},
  {"id":"unitools-vitumbua","name":"Витумбуа","description":"Рисовые оладьи на кокосовом молоке, выпеченные в сковороде с полусферическими лунками.","searchNames":["Vitumbua"],"category":"Завтраки","tags":["Танзанийская кухня"],"ingredients":[["fdc-168877",400.0,"Рис"],["fdc-170173",286.5738423981194,"Кокосовое молоко","300 мл"],["fdc-169655",120.0,"Сахар"],["fdc-175043",5.0,"Сухие дрожжи"],["fdc-170919",2.0,"Кардамон молотый","1 ч. л."],["fdc-170169",60.0,"Кокосовая стружка"],["fdc-172336",110.5718542350266,"Растительное масло","120 мл"]],"servings":8,"prep":40,"cook":30,"difficulty":"Средний","steps":["Слейте воду с замоченного риса и перемелите его с кокосовым молоком в гладкое жидкое тесто.","Вмешайте дрожжи, сахар, кардамон, соль и кокосовую стружку.","Оставьте тесто бродить четыре часа в тепле, пока оно не покроется пузырями.","Размешайте тесто и проверьте густоту: оно должно литься лентой, а не падать комом.","Разогрейте сковороду с лунками и смажьте каждую маслом с помощью кисти.","Наполните лунки на три четверти и пеките три минуты, пока края не схватятся.","Переверните оладьи шпажкой и допеките ещё три минуты до румяного шара."],"source":"UniTools — theunitools.com · CC BY-SA 4.0 · адаптация MassTracker","cuisine":"Танзанийская кухня","seasoningNote":"По вкусу, вне расчёта КБЖУ: Соль."},
  {"id":"unitools-souvlaki","name":"Сувлаки","description":"Свинина на шпажках в маринаде из лимона, орегано и оливкового масла, приготовленная быстро и на сильном жаре.","searchNames":["Souvlaki"],"category":"Основные блюда","tags":["Греческая кухня"],"ingredients":[["fdc-167843",800.0,"Свиная шея"],["fdc-171413",73.03828903598087,"Оливковое масло","80 мл"],["fdc-167746",58.0,"Лимон","1 шт."],["fdc-171328",2.0,"Сушёный орегано","2 ч. л."],["fdc-169230",9.0,"Чеснок","3 зубч."],["fdc-172816",240.0,"Питы","4 шт."],["fdc-171304",200.0,"Густой йогурт"],["fdc-168409",150.5,"Огурец","0,5 шт."]],"servings":4,"prep":20,"cook":15,"difficulty":"Простой","steps":["Смешайте масло, сок и цедру лимона, орегано, тёртый чеснок, соль и перец. Залейте мясо и оставьте на два часа, но не дольше четырёх.","Пока маринуется, сделайте дзадзики: смешайте йогурт с отжатым огурцом, зубчиком чеснока, ложкой масла и солью.","Нанижите мясо на шпажки неплотно — между кусками должен проходить жар. Плотно набитая шпажка внутри останется сырой.","Готовьте на раскалённом гриле или сковороде-гриль по три минуты с каждой из четырёх сторон. Мясо должно потемнеть, а не побледнеть.","Дайте мясу отдохнуть пять минут, прогрейте питы по тридцать секунд и подавайте с дзадзики и лимоном."],"source":"UniTools — theunitools.com · CC BY-SA 4.0 · адаптация MassTracker","cuisine":"Греческая кухня","seasoningNote":"По вкусу, вне расчёта КБЖУ: Соль и перец."},
  {"id":"unitools-roesti","name":"Рёшти","description":"Картофельный блин из крупной тёрки, обжаренный до корочки с двух сторон. Картофель отваривают накануне.","searchNames":["Rösti"],"category":"Гарниры","tags":["Швейцарская кухня"],"ingredients":[["fdc-170026",1000.0,"Восковой картофель","1 кг"],["fdc-171314",60.0,"Топлёное масло"],["fdc-168277",100.0,"Копчёный бекон"],["fdc-170000",110.0,"Лук","1 шт."],["fdc-171242",100.0,"Тёртый грюйер"]],"servings":4,"prep":15,"cook":30,"difficulty":"Простой","steps":["Отварите картофель в мундире двадцать минут — до состояния, когда нож входит с сопротивлением. Полностью остудите и оставьте на ночь в холодильнике.","Очистите и натрите на крупной тёрке прямо в миску. Не промывайте и не отжимайте.","Посолите, поперчите и, если используете, вмешайте обжаренные бекон с луком и сыр.","Разогрейте половину масла в сковороде, выложите массу ровным слоем и придавите лопаткой один раз.","Жарьте на среднем огне двенадцать минут, не трогая. Периодически потряхивайте сковороду — рёшти должен скользить целиком.","Накройте тарелкой, переверните, добавьте оставшееся масло и жарьте вторую сторону ещё десять минут."],"source":"UniTools — theunitools.com · CC BY-SA 4.0 · адаптация MassTracker","cuisine":"Швейцарская кухня","seasoningNote":"По вкусу, вне расчёта КБЖУ: Соль и перец."},
  {"id":"unitools-sukuma-wiki","name":"Сукума-вики","description":"Тушёная листовая капуста с луком и помидорами. Ежедневный гарнир к угали по всей Восточной Африке.","searchNames":["Sukuma wiki"],"category":"Гарниры","tags":["Кенийская кухня"],"ingredients":[["fdc-170406",700.0,"Листовая капуста"],["fdc-170000",220.0,"Лук","2 шт."],["fdc-170457",492.0,"Помидоры","4 шт."],["fdc-169230",12.0,"Чеснок","4 зубч."],["fdc-172336",46.07160593126108,"Растительное масло","50 мл"],["fdc-170923",2.5,"Зира молотая","1 ч. л."],["fdc-167746",58.0,"Лимон","1 шт."]],"servings":4,"prep":15,"cook":20,"difficulty":"Простой","steps":["Снимите с листьев жёсткие черешки, сверните листья в рулон и нарежьте тонкой соломкой.","Обжарьте лук в масле до мягкости, добавьте чеснок и зиру и прогрейте минуту.","Положите нарезанные помидоры и тушите семь минут, пока они не разойдутся в пасту.","Добавьте зелень, посолите и перемешайте. Она осядет вдвое за минуту.","Влейте полстакана воды, накройте и тушите десять минут — зелень должна стать мягкой, но остаться зелёной.","Сбрызните лимоном и подавайте с угали или рисом."],"source":"UniTools — theunitools.com · CC BY-SA 4.0 · адаптация MassTracker","cuisine":"Кенийская кухня","seasoningNote":"По вкусу, вне расчёта КБЖУ: Соль и перец."},
  {"id":"unitools-kholodnik","name":"Халаднік","description":"Холодный свекольник на кефире со щавелем, огурцом и яйцом, розовый и очень кислый.","searchNames":["Kholodnik"],"category":"Супы","tags":["Белорусская кухня"],"ingredients":[["fdc-169145",500.0,"Свёкла"],["fdc-170076",200.0,"Щавель"],["fdc-170904",1027.1009395684812,"Кефир","1 л"],["fdc-168409",903.0,"Огурцы","3 шт."],["fdc-171287",250.0,"Яйца","5 шт."],["fdc-170005",50.0,"Зелёный лук"],["fdc-172233",40.0,"Укроп"],["fdc-171257",194.43063053559723,"Сметана","200 мл"],["fdc-170026",800.0,"Картофель"],["fdc-172237",14.9,"Уксус","1 ст. л."]],"servings":5,"prep":25,"cook":45,"difficulty":"Простой","steps":["Отварите свёклу до мягкости с ложкой уксуса, чтобы она сохранила цвет, и полностью остудите.","Отварите щавель в небольшом количестве воды пять минут, пока он не потемнеет, и остудите.","Натрите остывшую свёклу на крупной тёрке, огурцы нарежьте соломкой.","Смешайте свёклу, щавель с его отваром, огурцы и зелень со сметаной и посолите.","Влейте холодный кефир и размешайте до ровного розового цвета.","Уберите в холодильник на час, чтобы суп настоялся и стал по-настоящему холодным.","Отварите картофель и подайте горячим отдельно, а в суп положите половинки яиц."],"source":"UniTools — theunitools.com · CC BY-SA 4.0 · адаптация MassTracker","cuisine":"Белорусская кухня","seasoningNote":"По вкусу, вне расчёта КБЖУ: Соль."},
];
